public class AopDemo {
    interface Calculator {
        int add(int a, int b);
    }
    static class RealCalculator implements Calculator {
        public int add(int a, int b) { return a + b; }
    }
    static class LoggingCalculator implements Calculator {
        private final Calculator delegate;
        LoggingCalculator(Calculator delegate) { this.delegate = delegate; }
        public int add(int a, int b) {
            // TODO: print "Before: add"
            int result = delegate.add(a, b);
            // TODO: print "After: add"
            return result;
        }
    }
    public static void main(String[] args) {
        Calculator calc = new LoggingCalculator(new RealCalculator());
        System.out.println(calc.add(3, 4));
    }
}

